<template>
	<view class="blacklist-page">
		<view class="fixed-header" :style="{ paddingTop: statusBarHeight + 'px' }">
			<view class="nav-bar">
				<view class="back-btn" @click="goBack">‹</view>
				<text class="nav-title">黑名单</text>
				<view class="placeholder" />
			</view>
		</view>

		<scroll-view class="blacklist-scroll" scroll-y enhanced :show-scrollbar="false" :style="{ paddingTop: headerHeight + 'px' }">
			<view v-if="loading" class="page-state">正在加载...</view>
			<view v-else-if="!users.length" class="page-state">
				<text class="empty-title">黑名单为空</text>
				<text class="empty-copy">被拉黑的用户会显示在这里</text>
			</view>
			<view v-else class="user-list">
				<view v-for="user in users" :key="user.id" class="user-row">
					<image class="avatar" :src="user.avatar || defaultAvatar" mode="aspectFill" />
					<view class="user-main">
						<text class="user-name">{{ user.name }}</text>
						<text class="user-meta">{{ formatMeta(user) }}</text>
					</view>
					<button class="remove-btn" :disabled="submittingId === user.id" @click="confirmUnblock(user)">
						{{ submittingId === user.id ? '处理中' : '解除' }}
					</button>
				</view>
			</view>
			<view class="bottom-safe" />
		</scroll-view>
	</view>
</template>

<script>
import { DEFAULT_AVATAR_URL } from '../../config';
import { fetchBlockedUsers, unblockUser } from '../../api/user';
import { showRequestError } from '../../utils/feedback';

export default {
	data() {
		return {
			statusBarHeight: 44,
			headerHeight: 96,
			loading: false,
			submittingId: '',
			users: [],
			defaultAvatar: DEFAULT_AVATAR_URL
		};
	},
	onLoad() {
		this.setHeaderHeight();
		this.loadUsers();
	},
	methods: {
		setHeaderHeight() {
			try {
				const info = uni.getSystemInfoSync();
				this.statusBarHeight = info.statusBarHeight || 44;
				const rpxToPx = (info.windowWidth || 375) / 750;
				this.headerHeight = this.statusBarHeight + Math.round(96 * rpxToPx);
			} catch (error) {
				this.headerHeight = 96;
			}
		},
		async loadUsers() {
			this.loading = true;
			try {
				const result = await fetchBlockedUsers();
				this.users = Array.isArray(result && result.items) ? result.items : [];
			} catch (error) {
				showRequestError(error, '黑名单加载失败');
			} finally {
				this.loading = false;
			}
		},
		formatMeta(user) {
			return [user.gender, user.age ? `${user.age}岁` : '', user.city].filter(Boolean).join(' · ') || '同频旅人';
		},
		confirmUnblock(user) {
			if (!user || !user.id || this.submittingId) return;
			uni.showModal({
				title: '解除拉黑？',
				content: `解除后，你们可以重新查看主页、互动和发起私信。`,
				confirmText: '解除',
				success: ({ confirm }) => {
					if (confirm) this.submitUnblock(user);
				}
			});
		},
		async submitUnblock(user) {
			this.submittingId = user.id;
			try {
				await unblockUser(user.id);
				this.users = this.users.filter((item) => item.id !== user.id);
				uni.showToast({ title: '已解除拉黑', icon: 'none' });
			} catch (error) {
				showRequestError(error, '解除失败');
			} finally {
				this.submittingId = '';
			}
		},
		goBack() {
			uni.navigateBack();
		}
	}
};
</script>

<style lang="scss" scoped>
.blacklist-page {
	min-height: 100vh;
	background: #f7f3f6;
}

.fixed-header {
	position: fixed;
	top: 0;
	left: 0;
	right: 0;
	z-index: 10;
	border-bottom: 1rpx solid #f0e5ea;
	background: rgba(255, 255, 255, 0.97);
}

.nav-bar {
	position: relative;
	display: flex;
	align-items: center;
	justify-content: space-between;
	height: 96rpx;
	padding: 0 28rpx;
}

.back-btn,
.placeholder {
	width: 72rpx;
	height: 72rpx;
}

.back-btn {
	display: flex;
	align-items: center;
	justify-content: center;
	color: #33262e;
	font-size: 52rpx;
}

.nav-title {
	position: absolute;
	left: 150rpx;
	right: 150rpx;
	color: #221820;
	font-size: 32rpx;
	font-weight: 700;
	text-align: center;
}

.blacklist-scroll {
	height: 100vh;
}

.user-list {
	margin-top: 16rpx;
	background: #ffffff;
}

.user-row {
	display: flex;
	align-items: center;
	gap: 20rpx;
	min-height: 116rpx;
	padding: 18rpx 28rpx;
	box-sizing: border-box;
}

.user-row + .user-row {
	border-top: 1rpx solid #f1ecef;
}

.avatar {
	width: 76rpx;
	height: 76rpx;
	border-radius: 50%;
	background: #eee8ec;
	flex-shrink: 0;
}

.user-main {
	flex: 1;
	min-width: 0;
}

.user-name,
.user-meta {
	display: block;
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
}

.user-name {
	color: #2c2229;
	font-size: 28rpx;
	font-weight: 600;
}

.user-meta {
	margin-top: 8rpx;
	color: #9b8d95;
	font-size: 22rpx;
}

.remove-btn {
	display: flex;
	align-items: center;
	justify-content: center;
	width: 112rpx;
	height: 58rpx;
	margin: 0;
	border: 1rpx solid #dfccd4;
	border-radius: 8rpx;
	background: #ffffff;
	color: #7c5c69;
	font-size: 23rpx;
	line-height: 1;
}

.remove-btn::after {
	border: 0;
}

.page-state {
	display: flex;
	flex-direction: column;
	align-items: center;
	justify-content: center;
	min-height: 420rpx;
	color: #9b8d95;
	font-size: 25rpx;
}

.empty-title {
	color: #4c3f47;
	font-size: 30rpx;
	font-weight: 600;
}

.empty-copy {
	margin-top: 12rpx;
	color: #a99ca4;
	font-size: 23rpx;
}

.bottom-safe {
	height: calc(36rpx + env(safe-area-inset-bottom));
}
</style>
